DO $migration$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.competitive_ranking()'::regprocedure) INTO definition; definition:=replace(definition,'DECLARE result jsonb;','DECLARE ranking_payload jsonb;'); definition:=replace(definition,'INTO result;','INTO ranking_payload;'); definition:=replace(definition,'RETURN result;','RETURN ranking_payload;'); EXECUTE definition; END $migration$;